steps.function:
(args) => {
  // Parse the v3-mail worker /emails list (include_body=true) and extract
  // the Notion verification code. Runs in the signup tab via chrome.debugger
  // — but the mail request itself went out from the service worker with the
  // Bearer token, so no mail tab and no admin session cookie are involved.
  try {
    const status = Number(args.status) || 0;
    if (status === 401 || status === 403) {
      return { code: null, fatal: true, error: 'mail API unauthorized (HTTP ' + status + ') — check the emailWorkerToken input (must be "Bearer <QUERY_API_TOKEN>")' };
    }
    const d = JSON.parse(args.body);
    const rows = d.results || [];
    const sinceId = Number(args.sinceId) || 0;
    // Notion-specific row filter: newer than the baseline id, subject looks
    // like a code email, AND the sender/subject mentions Notion.
    const CODEISH = /(code|verify|verification|login|log[- ]?in|passcode|confirm|signup|sign[- ]?up|otp|one[- ]?time|security)/i;
    let best = null;
    for (const r of rows) {
      const id = Number(r.id) || 0;
      if (sinceId && id <= sinceId) continue;
      const subject = r.subject || '';
      const from = r.from_header || '';
      if (!CODEISH.test(subject)) continue;
      if (!/notion/i.test(from + ' ' + subject)) continue;
      const ts = Date.parse(r.received_at || '') || 0;
      if (!best || ts > best.ts) best = { id: id, ts: ts, subject: subject, from: from, text: (r.text_body || '').trim(), received: r.received_at };
    }
    if (!best) return { code: null, reason: rows.length ? 'no new Notion code email yet' : 'no emails yet', rowCount: rows.length };
    const firstLine = (best.text.split(/\n/)[0] || '').trim(); let m = /^[A-Za-z0-9]{4,10}$/.test(firstLine) ? [firstLine, firstLine] : null; if (!m) m = best.text.match(/\b(?=\w*\d)(?=[^\s]*[A-Za-z])[A-Za-z0-9]{4,10}\b/) || best.text.match(/\b[A-Z0-9]{4,10}\b/); if (!m) m = best.subject.match(/\b([A-Za-z0-9]{4,10})\b/);
    if (!m) return { code: null, fatal: true, emailId: best.id, subject: best.subject.slice(0, 80), error: 'Notion code email arrived but no code found in body or subject' };
    return { code: m[1], source: best.text ? 'body' : 'subject', subject: best.subject.slice(0, 100), emailId: best.id, from: best.from.slice(0, 100), received: best.received };
  } catch (e) {
    return { code: null, error: String(e) };
  }
}
